import sys;sys.setrecursionlimit(10000)
from collections import deque
def comps(I,val):
    H,W=len(I),len(I[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if I[r][c]==val and not seen[r][c]:
                q=deque([(r,c)]); seen[r][c]=True; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and I[ny][nx]==val and not seen[ny][nx]:
                            seen[ny][nx]=True;q.append((ny,nx))
                out.append(cells)
    return out
